DO $x$ BEGIN IF pg_get_functiondef('public.customer_loyalty_completed_appointment_trigger()'::regprocedure) LIKE '%attendance_resolved_at%' THEN RAISE EXCEPTION 'loyalty_trigger_drift'; END IF; EXECUTE $p$CREATE OR REPLACE FUNCTION public.customer_loyalty_completed_appointment_trigger() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $f$ BEGIN IF NEW.status='completed' AND NEW.attendance_resolved_at IS NOT NULL AND (TG_OP='INSERT' OR OLD.status IS DISTINCT FROM NEW.status) THEN PERFORM public.process_customer_loyalty_for_completed_appointment(NEW.id); END IF; RETURN NEW; END; $f$$p$; END $x$;
